def minFallingPathNoRepeat(matrix):
    prev = matrix[0][:]
    for row in matrix[1:]:
        n = len(prev)
        i1 = min(range(n), key=lambda x: prev[x])
        m1 = prev[i1]
        m2 = min(prev[x] for x in range(n) if x != i1)
        prev = [row[c] + (m2 if c == i1 else m1) for c in range(n)]
    return min(prev)
